func prepare_for_draw(entry: Dictionary, ground: HexCourtPresenter, reduced: bool, sample_limit: int) -> Dictionary:
	# Preserve existing virtual calls for derived Surface, ground or court hooks.
	var court: Variant = entry.get("court")
	if get_script().resource_path != "res://.godot/iteration-20261014/garden-sample-next/candidate_surface.gd" or ground == null or ground.get_script().resource_path != "res://src/presentation/hex_court_presenter.gd" or not court is HexChemistryWorld:
		return prepare(entry, ground, reduced)
	if court.get_script().resource_path not in ["res://src/app/element_garden_court.gd", "res://src/sim/hex/hex_chemistry_world.gd"]:
		return prepare(entry, ground, reduced)
	return _prepare_samples(entry, ground, reduced, clampi(sample_limit, 1, MAX_SAMPLES))


